def check_following(response):
    paragraphs = [para.strip() for para in response.split("\n") if para.strip()]
    if len(paragraphs) < 3:
        return False
    for paragraph in paragraphs:
        sentences = re.split(r'[.!?](?:\s|$)', paragraph.strip())
        sentences = [s for s in sentences if s.strip()]
        if len(sentences) > 4:
            return False
    return True

